#include <iostream>
#include <vector>
#include <string>
#include <array>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;
    vector<string> words(m);
    for (int i = 0; i < m; i++) {
        cin >> words[i];
    }
    string t;
    cin >> t;

    vector<array<int, 26>> nxt(1);
    nxt[0].fill(-1);
    vector<int> fail(1, 0);
    vector<long long> cnt(1, 0);
    for (long long wi = 0; wi < m; wi++) {
        int node = 0;
        for (char ch : words[wi]) {
            int c = ch - 'a';
            if (nxt[node][c] == -1) {
                nxt[node][c] = (int)nxt.size();
                array<int, 26> blank;
                blank.fill(-1);
                nxt.push_back(blank);
                fail.push_back(0);
                cnt.push_back(0);
            }
            node = nxt[node][c];
        }
        cnt[node]++;
    }
    vector<int> queue;
    for (int c = 0; c < 26; c++) {
        int v = nxt[0][c];
        if (v == -1) nxt[0][c] = 0;
        else queue.push_back(v);
    }
    for (size_t head = 0; head < queue.size(); head++) {
        int u = queue[head];
        cnt[u] += cnt[fail[u]];
        for (int c = 0; c < 26; c++) {
            int v = nxt[u][c];
            if (v == -1) {
                nxt[u][c] = nxt[fail[u]][c];
            } else {
                fail[v] = nxt[fail[u]][c];
                queue.push_back(v);
            }
        }
    }
    long long total = 0;
    int state = 0;
    for (char ch : t) {
        state = nxt[state][ch - 'a'];
        total += cnt[state];
    }
    cout << total << "\n";

    return 0;
}

